contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: amount, loanToCollateral, interest, duration
    function run(uint256 amount_, uint256 loanToCollateral_, uint256 interest_, uint256 duration_) public payable {
        require(loanToCollateral_ != 0 && amount_ != 0, "invalid inputs");

        // approve and transfer simulated by using the ERC20 interface externally is not possible here.
        // Instead we observe only public surface: call requestLoan and then check request stored and contract balance change.
        // To make the test observable without token transfers, we rely on collateralFor logic and request active flag.

        // Read requests length before
        uint256 beforeLen = c.requestsLength();

        // Call requestLoan; it will try to transfer collateral via token, which may revert. Capture revert.
        bool reverted;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 reqID) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the call did not revert, then the newly stored request must be active and match fields
        // We can read getRequest and isActive and check collateralFor relation via public collateralFor view.
        if (!reverted) {
            uint256 newLen = c.requestsLength();
            // exactly one new request appended
            bool oneAppended = newLen == beforeLen + 1;
            uint256 reqID = newLen - 1;
            C.Request memory req = c.getRequest(reqID);
            bool activeFlag = c.isActive(reqID);
            uint256 expectedCollat = c.collateralFor(req.amount, req.loanToCollateral);

            // Assert general property: request is active, request.amount equals provided amount, loanToCollateral equals provided, and collateralFor matches the contract's view
            assert(oneAppended && activeFlag && req.amount == amount_ && req.loanToCollateral == loanToCollateral_ && expectedCollat == c.collateralFor(amount_, loanToCollateral_));
        } else {
            // If it reverted, then there is no new request appended; ensure length unchanged
            uint256 afterLen = c.requestsLength();
            assert(afterLen == beforeLen);
        }
    }

    // helper to expose requests.length via a view call on C. This uses only public interface: relying on auto-generated getter for 'requests' array length
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: amount, loanToCollateral, interest, duration
    function run(uint256 amount_, uint256 loanToCollateral_, uint256 interest_, uint256 duration_) public payable {
        // avoid division by zero in collateralFor when loanToCollateral_ == 0
        require(loanToCollateral_ != 0, "bad input");

        // Read requests length before by calling public getter: requests(uint256) exists, so iterate until out-of-bounds to get length is impossible.
        // Instead, observe that auto-generated getter for public array 'requests' is requests(uint256) -> Request.
        // We cannot read length directly; use a conservative approach: try reading requests at increasing indices until a revert to determine length.
        uint256 beforeLen = 0;
        // probe up to a reasonable bound to find current length; since c is fresh per run, length is small. We'll probe until a call reverts.
        // We must catch reverts from view calls; use try/catch.
        for (uint256 i = 0; i < 50; i++) {
            try c.getRequest(i) returns (C.Request memory) {
                beforeLen = i + 1;
                continue;
            } catch {
                break;
            }
        }

        bool reverted;
        uint256 returnedReqID = type(uint256).max;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 reqID) {
            reverted = false;
            returnedReqID = reqID;
        } catch {
            reverted = true;
        }

        // Determine after length similarly
        uint256 afterLen = 0;
        for (uint256 i = 0; i < 50; i++) {
            try c.getRequest(i) returns (C.Request memory) {
                afterLen = i + 1;
                continue;
            } catch {
                break;
            }
        }

        // If reverted, length must be unchanged. If not reverted, length must have increased by exactly 1 and new request must be active and have matching amount and loanToCollateral, and collateralFor from that request equals calling c.collateralFor
        if (reverted) {
            assert(afterLen == beforeLen);
        } else {
            // must have appended exactly one
            bool lenInc = (afterLen == beforeLen + 1);
            uint256 reqID = returnedReqID;
            // If returnedReqID wasn't provided (some implementations might still succeed but not return), fall back to last index
            if (reqID == type(uint256).max) {
                reqID = afterLen - 1;
            }
            C.Request memory req = c.getRequest(reqID);
            bool activeFlag = c.isActive(reqID);
            uint256 collFromView = c.collateralFor(req.amount, req.loanToCollateral);
            // general rule assertion
            assert(lenInc && activeFlag && req.amount == amount_ && req.loanToCollateral == loanToCollateral_ && collFromView == c.collateralFor(amount_, loanToCollateral_));
        }
    }

    receive() external payable {}
}

