        bool didRevert;
        uint256 retReqID = type(uint256).max;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 reqID) {
            didRevert = false;
            retReqID = reqID;
        } catch {
            didRevert = true;
        }

