contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount, interest, loanToCollateral, duration
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(loanToCollateral_ != 0, "loanToCollateral must be non-zero to compute collateral");

        // ensure this contract has enough collateral token balance to transfer into c
        // We cannot mint tokens here; but tests run with fresh c and token behaviour is external.
        // We'll attempt the call and observe whether it reverts. If it succeeds, we assert the request recorded
        // is active and that c's view collateralFor matches the collateral that should have been transferred in.

        // Read number of requests before
        uint256 beforeLen = c.requests.length;

        bool reverted;
        // call requestLoan; msg.sender for c will be this contract
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 reqID) {
            reverted = false;
            // after-call observations
            // The request should exist at index reqID and be active
            C.Request memory req = c.getRequest(reqID);
            // collateral required by formula
            uint256 expectedCollat = c.collateralFor(amount_, loanToCollateral_);
            // We cannot directly observe how much collateral token was pulled from this contract (ERC20 transfers),
            // but we can check that the requests array length increased and the recorded request matches inputs and is active.
            // Also req.amount equals amount_ and req.active is true.
            assert(req.amount == amount_ && req.interest == interest_ && req.loanToCollateral == loanToCollateral_ && req.duration == duration_ && req.active == true && c.requests.length == beforeLen + 1 && expectedCollat >= 0);
        } catch {
            reverted = true;
            // If the call reverted, then no new request should have been added: length unchanged
            assert(c.requests.length == beforeLen);
        }

        // Final general invariant: either the call reverted and requests length unchanged, or it succeeded and the new request at the returned index is active and matches inputs.
        // The previous try/catch already enforces this with the asserts inside each branch; here we provide a single general assert over observable state.
        // Recompute a boolean form capturing the same:
        bool lenIncreased = (c.requests.length == beforeLen + 1);
        bool lenSame = (c.requests.length == beforeLen);
        // If increased, the last request must match and be active
        if (lenIncreased) {
            uint256 lastIdx = c.requests.length - 1;
            C.Request memory last = c.getRequest(lastIdx);
            assert(last.amount == amount_ && last.interest == interest_ && last.loanToCollateral == loanToCollateral_ && last.duration == duration_ && last.active == true);
        } else {
            assert(lenSame);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount, interest, loanToCollateral, duration
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(loanToCollateral_ != 0, "loanToCollateral must be non-zero");

        // Read number of requests before by calling getRequest in a loop until it reverts to find length.
        // Since requests is a public array, there is no direct length getter; use getRequest until it reverts.
        uint256 beforeLen = 0;
        // probe increasing indices until a call reverts
        for (uint256 i = 0; i < 1024; i++) {
            try c.getRequest(i) returns (C.Request memory) {
                beforeLen = i + 1;
                continue;
            } catch {
                break;
            }
        }

        bool callReverted;
        uint256 returnedReqID = type(uint256).max;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 reqID) {
            callReverted = false;
            returnedReqID = reqID;
        } catch {
            callReverted = true;
        }

        // Determine after length similarly
        uint256 afterLen = 0;
        for (uint256 i = 0; i < 1024; i++) {
            try c.getRequest(i) returns (C.Request memory) {
                afterLen = i + 1;
                continue;
            } catch {
                break;
            }
        }

        // General invariant: if call reverted, length unchanged; otherwise length increased by 1 and the new request at returnedReqID matches inputs and is active.
        if (callReverted) {
            assert(afterLen == beforeLen);
        } else {
            assert(afterLen == beforeLen + 1);
