    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(loanToCollateral_ != 0, "loanToCollateral must be nonzero for division");

        // prepare: msg.sender for c calls will be this contract
        // Approve behavior: we cannot call ERC20.approve from here for collateral token because we don't control balances.
        // Instead we only observe the general property relating request state and collateral balance change

        // Read balance of c before
        address collateralAddr = address(c.collateral());
        uint256 balBefore = collateralAddr.balance;

        // Call requestLoan — this will try to transfer collateral from msg.sender to c, which is this contract.
        // To satisfy transferFrom, the collateral token might revert; we capture whether the call reverted.
        bool reverted;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After-call observations
        uint256 balAfter = collateralAddr.balance;
        uint256 reqCount = c.requests().length;

        // If the call did not revert, then:
        // - a new request should have been appended (requests length increased by 1)
        // - the new request should be active
        // - the stored fields amount, interest, loanToCollateral, duration equal the inputs
        // - the contract's collateral balance should be >= balBefore (since collateral was transferred in)

        if (!reverted) {
            C.Request memory r = c.getRequest(reqCount - 1);
            assert(
                r.active == true &&
                r.amount == amount_ &&
                r.interest == interest_ &&
                r.loanToCollateral == loanToCollateral_ &&
                r.duration == duration_ &&
                balAfter >= balBefore
            );
        } else {
            // If reverted, then no new request must have been appended and balances unchanged
            assert(reqCount == 0 || c.getRequest(reqCount - 1).amount != amount_ || balAfter == balBefore);
        }
    }

