            bool clearReverted;
            try c.clearRequest(0, repayDirect_, isCallback_) returns (uint256 lid) {
                clearReverted = false;
            } catch {
                clearReverted = true;
            }
            // General rule: if we couldn't create the request (requestLoan reverted), then trying to clear request 0 must revert (can't clear non-existent/untouched request)
            assert(reqReverted == clearReverted);
