        // So we treat 'requester' as an input but actually the requester will be address(this).
        // Create a request from this contract (msg.sender == address(this)).
        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_);

        // read the request and ensure it's active before clearing
        C.Request memory reqBefore = c.getRequest(reqID);

        // Now call clearRequest as the lender (this contract). clearRequest will transfer debt from msg.sender (this) to owner.
        // To avoid revert in safeTransferFrom inside clearRequest, we cannot ensure ERC20 allowances here; but clearRequest calls debt().safeTransferFrom(msg.sender, owner(), req.amount);
        // That call will likely revert unless token approves this contract. To make the property general and avoid dependence on token behavior, we catch revert.
        bool reverted;
        uint256 loanID;
        try c.clearRequest(reqID, false, false) returns (uint256 id) {
            reverted = false;
            loanID = id;
        } catch {
            reverted = true;
        }

        // Now assert the general rule: if clearRequest did NOT revert then
        //  - the request at reqID is no longer active
        //  - the created loan's lender equals the caller (address(this))
        //  - the created loan's amount is >= original req.amount
        // We observe these through public getters only.
        if (!reverted) {
            C.Request memory reqAfter = c.getRequest(reqID);
            C.Loan memory createdLoan = c.getLoan(loanID);
            assert(reqAfter.active == false && createdLoan.lender == address(this) && createdLoan.amount >= reqBefore.amount);
        } else {
            // If it reverted, we assert that no loan was created at that reqID: i.e., either isActive still true or some invariant holds relating to revert.
            // Simpler general rule: if clearRequest reverted then the original request remains active.
            C.Request memory reqNow = c.getRequest(reqID);
            assert(reqNow.active == true);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
