    constructor(C _c) { c = _c; }

    // params: amount, interest, loanToCollateral, duration
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(address(c) != address(0));

        // Create a request as msg.sender == address(this)
        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_);

        // Read request before attempting to clear
        C.Request memory reqBefore = c.getRequest(reqID);

        // Attempt to clearRequest; must be a top-level statement
        bool cleared;
        uint256 loanID;
        try c.clearRequest(reqID, false, false) returns (uint256 id) {
            cleared = true;
            loanID = id;
        } catch {
            cleared = false;
            loanID = type(uint256).max; // sentinel
        }

        // Read observable state after attempt
        C.Request memory reqAfter = c.getRequest(reqID);
        C.Loan memory maybeLoan = cleared ? c.getLoan(loanID) : C.Loan({request: C.Request({amount:0,interest:0,loanToCollateral:0,duration:0,active:false}), amount:0, unclaimed:0, collateral:0, expiry:0, lender:address(0), repayDirect:false, callback:false});

        // Single general assert covering both cases
        assert(
            (cleared && reqAfter.active == false && maybeLoan.lender == address(this) && maybeLoan.amount >= reqBefore.amount)
            ||
            (!cleared && reqAfter.active == true)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount (request amount), interest, loanToCollateral, duration, repay (attempted repay amount)
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, uint256 repay_) public payable {
        require(address(c) != address(0));
        // keep values small-ish to avoid extreme overflows in helpers
        require(loanToCollateral_ != 0 && duration_ != 0);

        // Create a request as this contract
        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_);

        // Clear the request to create a loan; this call may revert, capture that
        uint256 loanID;
        bool cleared;
        try c.clearRequest(reqID, true, false) returns (uint256 id) {
            cleared = true;
            loanID = id;
        } catch {
            cleared = false;
            loanID = type(uint256).max;
        }

        // If clearRequest failed we cannot proceed meaningful repay test; assert vacuously
        if (!cleared) {
            assert(!cleared);
            return;
        }

        // Observe loan before repay via public getter
        C.Loan memory loanBefore = c.getLoan(loanID);

        // Cap repay to a reasonable nonzero value to exercise nonzero decollateralized case
        uint256 attemptedRepay = repay_;
        if (attemptedRepay == 0) attemptedRepay = 1;

        // Perform repayLoan; catch revert
        bool reverted;
        uint256 decollateralized;
        try c.repayLoan(loanID, attemptedRepay) returns (uint256 d) {
            reverted = false;
            decollateralized = d;
        } catch {
            reverted = true;
            decollateralized = 0;
        }

        // If call reverted then nothing to check about arithmetic; assert revert flag implies decollateralized==0
        if (reverted) {
            assert(reverted && decollateralized == 0);
            return;
        }

        // If nonzero decollateralized, it must satisfy: decollateralized * loan.amount_before == loan.collateral_before * repaid_effective
        // Where repaid_effective = min(attemptedRepay, loanBefore.amount)
        uint256 repaid_effective = attemptedRepay;
        if (attemptedRepay > loanBefore.amount) repaid_effective = loanBefore.amount;

        // General invariant check
        assert(
            decollateralized == 0 || (decollateralized * loanBefore.amount == loanBefore.collateral * repaid_effective)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount (request amount), interest, loanToCollateral, duration, repay (attempted repay amount)
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, uint256 repay_) public payable {
        // basic preconditions to avoid div-by-zero and trivial zero-collateral
        require(address(c) != address(0));
        require(loanToCollateral_ != 0 && duration_ != 0);
        // create a request (this may revert if transferFrom fails in collateral; require small amounts)
        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_);

        // clear the request to create a loan; if it reverts the test should fail to reach the assert, so catch
        uint256 loanID;
        bool cleared;
        try c.clearRequest(reqID, true, false) returns (uint256 id) {
            cleared = true;
            loanID = id;
        } catch {
            cleared = false;
            loanID = type(uint256).max;
        }

        // require that clearRequest succeeded so we have a loan to operate on
        require(cleared);

        // observe loan before repay
        C.Loan memory loanBefore = c.getLoan(loanID);

        // ensure there is some loan amount and collateral to make meaningful repay
        require(loanBefore.amount > 0 && loanBefore.collateral > 0);

        uint256 attemptedRepay = repay_ == 0 ? 1 : repay_;

        // perform repayLoan and capture revert or return value
        bool reverted;
        uint256 decollateralized;
        try c.repayLoan(loanID, attemptedRepay) returns (uint256 d) {
            reverted = false;
            decollateralized = d;
        } catch {
            reverted = true;
            decollateralized = 0;
        }

        // if it reverted, assert that it indeed reverted (simple consistency); otherwise check the proportionality
        if (reverted) {
            assert(reverted);
            return;
        }

        // effective repaid is min(attemptedRepay, loanBefore.amount)
        uint256 repaid_effective = attemptedRepay;
        if (attemptedRepay > loanBefore.amount) repaid_effective = loanBefore.amount;

        // General proportionality rule: either zero decollateralized, or exact proportionality holds
        assert(decollateralized == 0 || (decollateralized * loanBefore.amount == loanBefore.collateral * repaid_effective));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount_, interest_, loanToCollateral_, duration_, repay_
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, uint256 repay_) public payable {
        // Preconditions to avoid div-by-zero and trivial cases and to keep numeric sizes reasonable
        require(loanToCollateral_ != 0 && duration_ != 0);
        require(amount_ > 0 && amount_ < type(uint128).max);

        // Create a request; this may revert if collateral transferFrom fails in practice,
        // but the checker will consider executions where it succeeds.
        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_);

        // Clear the request to produce a loan. Must succeed for the test to continue.
        uint256 loanID = c.clearRequest(reqID, true, false);

        // Observe loan before repay using public getter
        C.Loan memory loanBefore = c.getLoan(loanID);
        // Ensure meaningful loan to test proportionality
        require(loanBefore.amount > 0 && loanBefore.collateral > 0);

        uint256 attempted = repay_ == 0 ? 1 : repay_;

        bool reverted;
        uint256 decollateralized;
        try c.repayLoan(loanID, attempted) returns (uint256 d) {
            reverted = false;
            decollateralized = d;
        } catch {
            reverted = true;
            decollateralized = 0;
        }

        // If the call reverted then assert that reverted is true (trivially holds) so we must reach a nontrivial assert: require it didn't revert
        require(!reverted);

        // effective repaid is min(attempted, loanBefore.amount)
        uint256 repaid_effective = attempted;
        if (attempted > loanBefore.amount) repaid_effective = loanBefore.amount;

        // General rule: returned decollateralized equals floor(loan.collateral_before * repaid_effective / loan.amount_before)
        // Rearranged to avoid fractions in assert: decollateralized * loanBefore.amount == (loanBefore.collateral * repaid_effective) - rem
        // But we assert exact proportionality using multiplication (no subtraction that can underflow in assert).
        assert(decollateralized * loanBefore.amount == (loanBefore.collateral * repaid_effective) / 1);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // amount_, interest_, loanToCollateral_, duration_ : used to create a request
    // We must be msg.sender == this contract when interacting with c; the factory-created checks use owner() etc.
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(true);

        // First create a request by calling requestLoan as an external account: msg.sender here is InvMutTest, which is acceptable.
        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_);

        // Now attempt to clear the request by calling clearRequest as a lender (msg.sender becomes InvMutTest).
        // clearRequest will transfer debt from msg.sender to owner(); to avoid revert due to token transfer failing,
        // we cannot guarantee external ERC20 behavior. However, clearRequest may revert for many reasons.
        // We catch whether it reverted and observe post-state.
        bool reverted;
        uint256 loanID;
        try c.clearRequest(reqID, false, false) returns (uint256 l) {
            reverted = false;
            loanID = l;
        } catch {
            reverted = true;
            loanID = type(uint256).max;
        }

        // Read observable state: whether request is active and, if cleared, the created loan's lender and contained request.active
        bool reqActive = c.isActive(reqID);

        // If the clearRequest call did not revert, then the request that was cleared must now be inactive,
        // and the created loan's lender must be address(this). Also the loan's stored request.active must be false.
        // If it reverted, we don't require these relations.
        if (!reverted) {
            C.Request memory loanReq = c.getLoan(loanID).request;
            address lender = c.getLoan(loanID).lender;
            // Assert the general rule stated above
            assert(reqActive == false && lender == address(this) && loanReq.active == false);
        } else {
            // If reverted, assert must still be a general statement over public observations: we assert that when reverted,
            // either request remains active or no loan was created (loanID == max). This keeps the overall property general.
            // Note: we still must have exactly one assert overall; move to single assert combining both branches.
            assert(true);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Create a request, then attempt to clear it. If clearRequest succeeds, assert the invariants about request and loan.
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(true);

        // Create a request; this is a state-changing top-level call.
        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_);

        // Attempt to clear the request; must be a top-level call. Capture success via try/catch.
        bool cleared;
        uint256 loanID;
        try c.clearRequest(reqID, false, false) returns (uint256 l) {
            cleared = true;
            loanID = l;
        } catch {
            cleared = false;
            loanID = type(uint256).max;
        }

        // Observe public state after the attempt.
        bool reqActive = c.isActive(reqID);

        C.Loan memory observedLoan = C.Loan({
            request: C.Request({amount:0, interest:0, loanToCollateral:0, duration:0, active:false}),
            amount:0,
            unclaimed:0,
            collateral:0,
            expiry:0,
            lender:address(0),
            repayDirect:false,
            callback:false
        });

        // If cleared we can read the loan; if not cleared, keep a dummy loan where lender==address(0).
        if (cleared) {
            observedLoan = c.getLoan(loanID);
        }

        // Single general assert: if clearRequest succeeded, then the original request must be inactive,
        // the created loan's lender must be this contract, and the loan's embedded request.active must be false.
        // If clearRequest reverted, we make no extra obligations (the implication is vacuously true).
        assert(!cleared || (!reqActive && observedLoan.lender == address(this) && observedLoan.request.active == false));
    }

    receive() external payable {}
}
